package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.gateway.identity.AuthTokens;
import com.autocare.platform.vehicle.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import static com.autocare.platform.order.ReservationStore.*;

/** Rewards completed server actions from frozen evidence, never legacy balances or client claims. */
public class PointLedger {
 private final ReservationStore db;private final PointTaskPolicies policies;private final String appId;private final boolean enabled,aiEnabled;private final java.util.function.BooleanSupplier aiSource;
 public PointLedger(ReservationStore db,PointTaskPolicies policies,String appId,boolean enabled,boolean aiEnabled){this(db,policies,appId,enabled,aiEnabled,()->true);}
 public PointLedger(ReservationStore db,PointTaskPolicies policies,String appId,boolean enabled,boolean aiEnabled,java.util.function.BooleanSupplier aiSource){this.db=db;this.policies=policies;this.appId=appId;this.enabled=enabled;this.aiEnabled=aiEnabled;this.aiSource=aiSource;}
 public void recordIdentity(String session,long user,String app,boolean verified){db.jdbc.update("UPDATE auth_session SET point_identity_source=? WHERE id=? AND subject_type='user' AND role='OWNER' AND subject_id=? AND app_id=? AND point_identity_source='UNKNOWN'",verified&&appId.equals(app)&&!appId.isBlank()?"VERIFIED_WECHAT":"UNKNOWN",session,user,app);}
 private boolean eligible(VehicleOwner a,boolean lock){return verifiedIdentity(a,lock)&&enabled;}
 boolean verifiedIdentity(VehicleOwner a,boolean lock){db.owner(a,lock);return !appId.isBlank()&&!db.jdbc.queryForList("SELECT id FROM auth_session WHERE id=? AND subject_id=? AND subject_type='user' AND role='OWNER' AND app_id=? AND point_identity_source='VERIFIED_WECHAT' AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP()"+(lock?" FOR UPDATE":""),a.session(),a.id(),appId).isEmpty();}
 private String day(){return db.now().atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString();}
 private static org.springframework.web.server.ResponseStatusException conflict(){return new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"当前积分资格、任务日期或规则已变化，请重新读取");}
 private Map<String,Object> policy(String task){var rows=db.jdbc.queryForList("SELECT * FROM point_task_policy WHERE task_type=? AND status='PUBLISHED' FOR UPDATE",task);return rows.size()==1?rows.get(0):null;}
 private boolean active(Map<String,Object> p,Instant at){return p!=null&&!instant(p.get("valid_from")).isAfter(at)&&instant(p.get("valid_to")).isAfter(at);}
 private Map<String,Object> event(long user,String task,String period,boolean lock){var rows=db.jdbc.queryForList("SELECT * FROM point_task_event WHERE user_id=? AND task_type=? AND period_key=?"+(lock?" FOR UPDATE":""),user,task,period);return rows.isEmpty()?null:rows.get(0);}
 private void audit(long user,String action,String resource,long id,Object after){boolean system=action.equals("POINT_TASK_CREDIT");db.jdbc.update("INSERT INTO audit_log(actor_type,actor_id,action,resource_type,resource_id,before_state,after_state,request_id) VALUES(?,?,?,?,?,'{}',?,?)",system?"system":"user",system?0:user,action,resource,id,db.json(after),UUID.randomUUID().toString());}
 private Map<String,Object> capture(VehicleOwner a,String task,String period,Map<String,Object> p,String source,long revision,String hash,Instant at){
  if(!TransactionSynchronizationManager.isActualTransactionActive()||TransactionSynchronizationManager.isCurrentTransactionReadOnly())throw new IllegalStateException("Point evidence requires a write transaction");
  var old=event(a.id(),task,period,true);if(old!=null)return old;
  long id=db.insert("INSERT INTO point_task_event(user_id,task_type,period_key,policy_id,policy_revision,points,policy_snapshot,identity_session,source_id,source_revision,source_hash,occurred_at,next_attempt_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",a.id(),task,period,p.get("id"),p.get("revision"),p.get("points"),db.json(policies.view(p)),a.session(),source,revision,hash,time(at),time(at));
  audit(a.id(),"POINT_TASK_CAPTURE","point_task_event",id,Map.of("task_type",task,"period_key",period,"policy_id",p.get("id"),"policy_revision",p.get("revision"),"points",p.get("points")));return db.one("SELECT * FROM point_task_event WHERE id=?",id);
 }
 public static boolean completeManual(int type,JsonNode fields){if(!Set.of(1,2,10).contains(type)||!(fields instanceof ObjectNode o)||!fields.path("owner_confirmed").asBoolean())return false;try{new ArchiveStructuredInput(0,o).validateFor(type);return true;}catch(org.springframework.web.server.ResponseStatusException invalid){return false;}}
 /** Invoked only for an incomplete-to-complete transition in the source save transaction. */
 public void archiveCompleted(VehicleOwner a,long archive){if(!enabled)return;if(!eligible(a,true))return;var p=policy("ARCHIVE_FIRST_COMPLETE");if(!eligible(a,true))return;
  var rows=db.jdbc.queryForList("SELECT a.archive_type,s.revision,s.fields_json FROM vehicle_archive a JOIN vehicle v ON v.id=a.vehicle_id AND v.user_id=? AND v.is_deleted=0 JOIN archive_structured_detail s ON s.archive_id=a.id AND s.user_id=? AND s.vehicle_id=v.id AND s.is_deleted=0 WHERE a.id=? AND a.input_type IN (1,3) AND a.archive_type IN (1,2,10) AND a.is_deleted=0 FOR UPDATE",a.id(),a.id(),archive);if(rows.size()!=1)return;var r=rows.get(0);var fields=db.parse(r.get("fields_json"));var at=db.now();if(!completeManual((int)number(r,"archive_type"),fields)||!active(p,at))return;capture(a,"ARCHIVE_FIRST_COMPLETE","LIFETIME",p,"archive:"+archive,number(r,"revision"),AuthTokens.sha256(fields.toString()),at);
 }
 /** Called after a real upstream success; rechecks current identity after external IO. */
 public void aiSucceeded(VehicleOwner a,String content,String model,boolean official){if(!enabled||!aiEnabled||!aiSource.getAsBoolean()||!official||content==null||content.isBlank())return;db.transactions.executeWithoutResult(tx->{if(!eligible(a,true))return;var p=policy("AI_FIRST_SUCCESS");if(!eligible(a,true))return;var at=db.now();if(!active(p,at))return;capture(a,"AI_FIRST_SUCCESS","LIFETIME",p,UUID.randomUUID().toString(),1,AuthTokens.sha256(model+"\n"+content),at);});}
 static JsonNode checkinInput(String raw){var b=CouponInput.parse(raw);CouponInput.exact(b,"day","policy_id","policy_revision");if(!b.path("day").isTextual()||!b.path("day").asText().matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw ReservationInput.bad();try{LocalDate.parse(b.path("day").asText());}catch(RuntimeException e){throw ReservationInput.bad();}CouponInput.id(b.get("policy_id"));CouponInput.id(b.get("policy_revision"));return b;}
 private String hash(JsonNode b){var sorted=new TreeMap<String,JsonNode>();b.fields().forEachRemaining(e->sorted.put(e.getKey(),e.getValue()));return AuthTokens.sha256(db.json(sorted));}
 private Map<String,Object> map(Object json){return db.mapper.convertValue(db.parse(json),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});}
 public JsonNode checkin(VehicleOwner a,String key,JsonNode b){String canonical=WriteIntegrityService.normalizeKey(key),hash=hash(b);return db.writes.execute(new Actor("user",a.id()),"POST","/api/point/check-in",key,b,()->db.owner(a,true),()->{
  var prior=db.jdbc.queryForList("SELECT submission_hash,event_id,creation_result FROM point_checkin_request WHERE user_id=? AND submission_key=?",a.id(),canonical);if(!prior.isEmpty()){var old=prior.get(0);if(!hash.equals(old.get("submission_hash")))throw ReservationInput.bad();return new Change("POINT_CHECK_IN","point_task_event",number(old,"event_id"),Map.of(),Map.of(),map(old.get("creation_result")),false);}
  if(!eligible(a,true))throw conflict();var p=policy("CHECK_IN");if(!eligible(a,true))throw conflict();var at=db.now();String checkedDay=at.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString();if(!checkedDay.equals(b.path("day").asText())||!active(p,at)||number(p,"id")!=b.path("policy_id").asLong()||number(p,"revision")!=b.path("policy_revision").asLong())throw conflict();var e=capture(a,"CHECK_IN",checkedDay,p,"check-in:"+checkedDay,1,hash,at);
  var result=Map.<String,Object>of("event_id",e.get("id"),"day",e.get("period_key"),"status",e.get("status"),"points",e.get("points"));db.jdbc.update("INSERT INTO point_checkin_request(user_id,submission_key,submission_hash,event_id,creation_result,created_at) VALUES(?,?,?,?,?,?)",a.id(),canonical,hash,e.get("id"),db.json(result),time(db.now()));return new Change("POINT_CHECK_IN","point_task_event",number(e,"id"),Map.of(),Map.of(),result,false);
 });}
 @Scheduled(fixedDelayString="${POINTS_RECOVERY_DELAY_MS:5000}") public void recover(){if(!enabled)return;for(long id:db.jdbc.queryForList("SELECT e.id FROM point_task_event e JOIN user u ON u.id=e.user_id AND u.status=1 AND u.is_deleted=0 WHERE e.status='PENDING' AND e.next_attempt_at<=? ORDER BY e.id LIMIT 20",Long.class,time(db.now())))try{credit(id);}catch(RuntimeException failure){try{db.transactions.executeWithoutResult(tx->db.jdbc.update("UPDATE point_task_event SET attempts=LEAST(attempts+1,1000000),next_attempt_at=DATE_ADD(?,INTERVAL 30 SECOND),last_error='CREDIT_UNAVAILABLE' WHERE id=? AND status='PENDING'",time(db.now()),id));}catch(RuntimeException unavailable){/* PENDING evidence remains durable. */}}}
 boolean credit(long id){if(!enabled)return false;return Boolean.TRUE.equals(db.transactions.execute(tx->{var refs=db.jdbc.queryForList("SELECT user_id FROM point_task_event WHERE id=?",id);if(refs.isEmpty())return false;long user=number(refs.get(0),"user_id");var owners=db.jdbc.queryForList("SELECT id FROM user WHERE id=? AND status=1 AND is_deleted=0 FOR UPDATE",user);if(owners.isEmpty())return false;var rows=db.jdbc.queryForList("SELECT * FROM point_task_event WHERE id=? AND status='PENDING' AND next_attempt_at<=? FOR UPDATE SKIP LOCKED",id,time(db.now()));if(rows.isEmpty())return false;var e=rows.get(0);
  db.jdbc.update("INSERT IGNORE INTO point_verified_account(user_id,updated_at) VALUES(?,?)",user,time(db.now()));var account=db.one("SELECT balance,revision FROM point_verified_account WHERE user_id=? FOR UPDATE",user);long next=Math.addExact(number(account,"balance"),number(e,"points"));if(next>9007199254740991L)throw new IllegalStateException("Point balance overflow");db.jdbc.update("INSERT INTO point_verified_entry(user_id,event_id,delta,balance_after,created_at) VALUES(?,?,?,?,?)",user,id,e.get("points"),next,time(db.now()));db.jdbc.update("UPDATE point_verified_account SET balance=?,revision=revision+1,updated_at=? WHERE user_id=?",next,time(db.now()),user);audit(user,"POINT_TASK_CREDIT","point_task_event",id,Map.of("user_id",user,"delta",e.get("points"),"balance_after",next));db.jdbc.update("UPDATE point_task_event SET status='CREDITED',credited_at=?,last_error=NULL WHERE id=?",time(db.now()),id);return true;
 }));}
 public Map<String,Object> rules(VehicleOwner a){return db.reads.execute(tx->{var n=new LinkedHashMap<String,Object>(policies.current(a));n.put("earning_available",eligible(a,false));return n;});}
 public Map<String,Object> overview(VehicleOwner a){return db.reads.execute(tx->{boolean can=eligible(a,false);var rules=policies.current(a);var account=db.jdbc.queryForList("SELECT balance,revision FROM point_verified_account WHERE user_id=?",a.id());long balance=account.isEmpty()?0:number(account.get(0),"balance");boolean legacy=db.jdbc.queryForObject("SELECT point_balance FROM user WHERE id=?",Long.class,a.id())!=0||db.jdbc.queryForObject("SELECT COUNT(*) FROM point_flow WHERE user_id=?",Long.class,a.id())>0;var tasks=new ArrayList<Map<String,Object>>();for(var raw:(List<?>)rules.get("tasks")){var r=(Map<?,?>)raw;String type=r.get("task_type").toString();var e=event(a.id(),type,type.equals("CHECK_IN")?day():"LIFETIME",false);var n=new LinkedHashMap<String,Object>();n.put("task_type",type);n.put("frequency",r.get("frequency"));n.put("policy",e==null?r.get("policy"):db.parse(e.get("policy_snapshot")));n.put("state",e!=null?e.get("status"):!"CONFIGURED".equals(r.get("state"))?r.get("state"):!can?"IDENTITY_UNVERIFIED":type.equals("AI_FIRST_SUCCESS")&&(!aiEnabled||!aiSource.getAsBoolean())?"SOURCE_UNAVAILABLE":"READY");n.put("points_awarded",e!=null&&"CREDITED".equals(e.get("status"))?e.get("points"):0);n.put("occurred_at",e==null?null:iso(e.get("occurred_at")));n.put("credited_at",e==null?null:iso(e.get("credited_at")));tasks.add(n);}return Map.of("balance",balance,"balance_scope","VERIFIED_TASKS_V1","legacy_state",legacy?"REVIEW_REQUIRED":"NONE","earning_available",can,"day",day(),"timezone","Asia/Shanghai","tasks",tasks);});}
 public Map<String,Object> flow(VehicleOwner a,int p){if(p<1||p>1000000)throw ReservationInput.bad();return db.reads.execute(tx->{db.owner(a,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM point_verified_entry WHERE user_id=?",Long.class,a.id());var items=new ArrayList<Map<String,Object>>();for(var r:db.jdbc.queryForList("SELECT l.id,l.delta,l.balance_after,l.created_at,l.exchange_id,e.task_type,e.period_key,e.policy_id,e.policy_revision,x.catalog_id,x.catalog_revision,x.coupon_id FROM point_verified_entry l LEFT JOIN point_task_event e ON e.id=l.event_id AND e.user_id=l.user_id LEFT JOIN point_exchange_record x ON x.id=l.exchange_id AND x.user_id=l.user_id WHERE l.user_id=? ORDER BY l.id DESC LIMIT 20 OFFSET ?",a.id(),(p-1)*20L)){var n=new LinkedHashMap<String,Object>();for(String k:List.of("id","delta","balance_after"))n.put(k,r.get(k));n.put("created_at",iso(r.get("created_at")));for(String k:r.get("exchange_id")==null?List.of("task_type","period_key","policy_id","policy_revision"):List.of("exchange_id","catalog_id","catalog_revision","coupon_id"))n.put(k,r.get(k));items.add(n);}return page(items,count,p,20);});}
}
